namespace sv_1a0d15d56abd4f9d9b5410756a9b4bc5.Services;

public sealed class Recipe
{
    public int Id { get; init; }
    public required string Title { get; init; }
    public required string Description { get; init; }
    public int PrepTimeMinutes { get; init; }
}

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> SeedData = new()
    {
        [1] = new List<Recipe>
        {
            new() { Id = 1, Title = "Margherita Pizza", Description = "Classic Neapolitan pizza with fresh mozzarella, basil, and San Marzano tomatoes.", PrepTimeMinutes = 30 },
            new() { Id = 2, Title = "Spaghetti Carbonara", Description = "Roman pasta with eggs, Pecorino Romano, guanciale, and black pepper.", PrepTimeMinutes = 25 },
            new() { Id = 3, Title = "Tiramisu", Description = "Layered coffee-soaked ladyfingers with mascarpone cream and cocoa.", PrepTimeMinutes = 40 },
        },
        [2] = new List<Recipe>
        {
            new() { Id = 4, Title = "Pad Thai", Description = "Stir-fried rice noodles with shrimp, tofu, peanuts, and tamarind sauce.", PrepTimeMinutes = 35 },
            new() { Id = 5, Title = "Green Curry", Description = "Aromatic coconut milk curry with Thai basil, bamboo shoots, and chicken.", PrepTimeMinutes = 45 },
            new() { Id = 6, Title = "Tom Yum Soup", Description = "Hot and sour soup with lemongrass, galangal, kaffir lime leaves, and prawns.", PrepTimeMinutes = 20 },
        },
        [3] = new List<Recipe>
        {
            new() { Id = 7, Title = "Tacos al Pastor", Description = "Marinated pork tacos with pineapple, cilantro, and onion on corn tortillas.", PrepTimeMinutes = 50 },
            new() { Id = 8, Title = "Guacamole", Description = "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", PrepTimeMinutes = 10 },
            new() { Id = 9, Title = "Churros", Description = "Fried dough pastry coated in cinnamon sugar, served with chocolate sauce.", PrepTimeMinutes = 30 },
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        await Task.Delay(2000, cancellationToken);

        if (SeedData.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

@page "/recipes/{CuisineId:int}"
@using sv_1a0d15d56abd4f9d9b5410756a9b4bc5.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation

<PageTitle>Recipes</PageTitle>

<h1>Recipes — @CuisineName</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Sort by:</label>
    <div class="btn-group ms-2" role="group">
        <button class="btn btn-sm @(Sort != "popular" ? "btn-primary" : "btn-outline-primary")"
                @onclick='() => SetSort("newest")'>Newest</button>
        <button class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")"
                @onclick='() => SetSort("popular")'>Popular</button>
    </div>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-auto">@_error</span>
        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border text-primary" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-3 d-inline-flex align-items-center gap-2 mb-3">
            <div class="spinner-border spinner-border-sm" role="status"></div>
            <span>Refreshing…</span>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-3 g-4">
        @foreach (var recipe in SortedRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                    </div>
                    <div class="card-footer text-body-secondary">
                        🕐 @recipe.PrepTimeMinutes min
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!SortedRecipes.Any())
    {
        <p class="text-muted">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    private string CuisineName => CuisineId switch
    {
        1 => "Italian",
        2 => "Thai",
        3 => "Mexican",
        _ => $"Cuisine {CuisineId}"
    };

    private IEnumerable<Recipe> SortedRecipes =>
        _recipes is null
            ? Enumerable.Empty<Recipe>()
            : Sort == "popular"
                ? _recipes.OrderBy(r => r.PrepTimeMinutes)
                : _recipes.OrderByDescending(r => r.Id);

    protected override async Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId)
            return;

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;

        var cuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(cuisineId, token);

            // Guard against a late completion after a newer request was issued
            if (token.IsCancellationRequested)
                return;

            _recipes = result;
            _loadedCuisineId = cuisineId;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected when the user switched cuisines or navigated away — ignore.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", cuisineId);
            _error = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private async Task RetryAsync()
    {
        await LoadRecipesAsync();
    }

    private void SetSort(string sort)
    {
        Navigation.NavigateTo(
            Navigation.GetUriWithQueryParameter("sort", sort));
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

